 * - 유료 재화 팩 구매 (StartPurchase)
 * - 비Steam 폴백: GConfig 기반 로컬 잔액
 */
UCLASS()
class WJWORLD_API UWjWorldCurrencySubsystem : public UGameInstanceSubsystem
{
