   135→bool UWjWorldCosmeticSubsystem::EquipItem(ECosmeticSlot Slot, FName ItemId)
   136→{
   137→	if (Slot == ECosmeticSlot::None)
   138→	{
   139→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("None 슬롯에 장착할 수 없습니다."));
   140→		return false;
   141→	}
   142→
   143→	if (!HasItem(ItemId))
   144→	{
   145→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'을 보유하고 있지 않습니다."), *ItemId.ToString());
   146→		return false;
   147→	}
   148→
   149→	// 카탈로그 검증: 슬롯 일치 확인
   150→	if (Catalog)
   151→	{
   152→		const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   153→		if (Def && Def->Slot != Slot)
   154→		{
   155→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("아이템 '%s'은 슬롯 %d에 장착할 수 없습니다 (정의된 슬롯: %d)."),
   156→				*ItemId.ToString(), static_cast<int32>(Slot), static_cast<int32>(Def->Slot));
   157→			return false;
   158→		}
   159→	}
   160→
   161→	CurrentLoadout.Equip(Slot, ItemId);
   162→	OnLoadoutChanged.Broadcast(Slot, ItemId);
   163→
   164→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("장착: 슬롯 %d ← %s"), static_cast<int32>(Slot), *ItemId.ToString());
   165→	return true;
   166→}
