   176→void UWjWorldCosmeticSubsystem::SaveLoadoutToLocal()
   177→{
   178→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CosmeticLoadout.ini");
   179→
   180→	for (const FCosmeticSlotEntry& Entry : CurrentLoadout.Entries)
   181→	{
   182→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), static_cast<int32>(Entry.Slot));
   183→		GConfig->SetString(*LoadoutConfigSection, *SlotKey, *Entry.ItemId.ToString(), ConfigFilePath);
   184→	}
   185→
   186→	GConfig->Flush(false, ConfigFilePath);
   187→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 저장 완료"));
   188→}
   189→
   190→void UWjWorldCosmeticSubsystem::LoadLoadoutFromLocal()
   191→{
   192→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CosmeticLoadout.ini");
   193→
   194→	CurrentLoadout.Reset();
   195→
   196→	for (int32 SlotIdx = static_cast<int32>(ECosmeticSlot::Head);
   197→		SlotIdx <= static_cast<int32>(ECosmeticSlot::Effect); ++SlotIdx)
   198→	{
   199→		FString SlotKey = FString::Printf(TEXT("Slot_%d"), SlotIdx);
   200→		FString ItemIdStr;
   201→		if (GConfig->GetString(*LoadoutConfigSection, *SlotKey, ItemIdStr, ConfigFilePath))
   202→		{
   203→			if (!ItemIdStr.IsEmpty())
   204→			{
   205→				CurrentLoadout.Equip(static_cast<ECosmeticSlot>(SlotIdx), FName(*ItemIdStr));
   206→			}
   207→		}
   208→	}
   209→
   210→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("로드아웃 로컬 로드 완료 (%d 슬롯)"), CurrentLoadout.Entries.Num());
   211→}
