   213→void UWjWorldCosmeticSubsystem::StartInventoryPolling()
   214→{
   215→	UWorld* World = GetWorld();
   216→	if (!World)
   217→	{
   218→		return;
   219→	}
   220→
   221→	// 100ms 간격으로 결과 폴링
   222→	World->GetTimerManager().SetTimer(
   223→		InventoryPollTimerHandle,
   224→		this,
   225→		&UWjWorldCosmeticSubsystem::PollSteamInventoryResult,
   226→		0.1f,
   227→		true
   228→	);
   229→
   230→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 폴링 시작"));
   231→}
