   233→void UWjWorldCosmeticSubsystem::StopInventoryPolling()
   234→{
   235→	UWorld* World = GetWorld();
   236→	if (World)
   237→	{
   238→		World->GetTimerManager().ClearTimer(InventoryPollTimerHandle);
   239→	}
   240→	bInventoryRequestPending = false;
   241→
   242→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("인벤토리 폴링 중지"));
   243→}
