   245→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   246→{
   247→#if WITH_STEAM
   248→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   249→	{
   250→		StopInventoryPolling();
   251→		return;
   252→	}
   253→
   254→	ISteamInventory* SteamInv = SteamInventory();
   255→	if (!SteamInv)
   256→	{
   257→		StopInventoryPolling();
   258→		return;
   259→	}
   260→
   261→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   262→
   263→	if (Status == k_EResultPending)
   264→	{
   265→		// 아직 대기 중 - 계속 폴링
   266→		return;
   267→	}
   268→
   269→	// 결과 처리
   270→	if (Status == k_EResultOK)
   271→	{
   272→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   273→		ParseInventoryResult();
   274→	}
   275→	else
   276→	{
   277→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   278→	}
   279→
   280→	// 정리
   281→	SteamInv->DestroyResult(PendingResultHandle);
   282→	PendingResultHandle = k_SteamInventoryResultInvalid;
   283→	StopInventoryPolling();
   284→
   285→	// 델리게이트 브로드캐스트
   286→	OnInventoryUpdated.Broadcast();
   287→#else
   288→	StopInventoryPolling();
   289→#endif
   290→}
