    46→void AWjWorldPlacedObjectActor::LoadMesh(const FPlaceableObjectDefinition& Definition)
    47→{
    48→	if (!Definition.Mesh.IsNull())
    49→	{
    50→		FSoftObjectPath MeshPath = Definition.Mesh.ToSoftObjectPath();
    51→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacedObjectActor::LoadMesh - Starting async load for ObjectId=%s, Path=%s"),
    52→			*ObjectId.ToString(), *MeshPath.ToString());
    53→
    54→		MeshLoadHandle = StreamableManager.RequestAsyncLoad(
    55→			MeshPath,
    56→			FStreamableDelegate::CreateUObject(this, &AWjWorldPlacedObjectActor::OnMeshLoaded)
    57→		);
    58→
    59→		if (!MeshLoadHandle.IsValid())
    60→		{
    61→			UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::LoadMesh - RequestAsyncLoad returned invalid handle for ObjectId=%s"), *ObjectId.ToString());
    62→		}
    63→	}
    64→	else
    65→	{
    66→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacedObjectActor: Mesh is null for ObjectId=%s"), *ObjectId.ToString());
    67→	}
    68→}
    69→
    70→void AWjWorldPlacedObjectActor::OnMeshLoaded()
    71→{
    72→	if (!MeshLoadHandle.IsValid())
    73→	{
    74→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - MeshLoadHandle is invalid for ObjectId=%s"), *ObjectId.ToString());
    75→		return;
    76→	}
    77→
    78→	if (!MeshLoadHandle->HasLoadCompleted())
    79→	{
    80→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - Load not completed for ObjectId=%s"), *ObjectId.ToString());
    81→		return;
    82→	}
    83→
    84→	UStaticMesh* LoadedMesh = Cast<UStaticMesh>(MeshLoadHandle->GetLoadedAsset());
    85→	if (!LoadedMesh)
    86→	{
    87→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - LoadedMesh is null for ObjectId=%s (Asset: %s)"),
    88→			*ObjectId.ToString(),
    89→			*MeshLoadHandle->GetDebugName());
    90→		return;
    91→	}
    92→
    93→	if (!MeshComponent)
    94→	{
    95→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacedObjectActor::OnMeshLoaded - MeshComponent is null for ObjectId=%s"), *ObjectId.ToString());
    96→		return;
    97→	}
    98→
    99→	MeshComponent->SetStaticMesh(LoadedMesh);
   100→	MeshComponent->SetWorldScale3D(CachedScale);
   101→
   102→	// 가시성 명시적으로 활성화
   103→	MeshComponent->SetVisibility(true);
   104→	MeshComponent->SetHiddenInGame(false);
   105→
   106→	// 머티리얼 체크
   107→	int32 NumMaterials = MeshComponent->GetNumMaterials();
   108→	FString MaterialInfo = FString::Printf(TEXT("NumMaterials=%d"), NumMaterials);
   109→	for (int32 i = 0; i < NumMaterials; ++i)
   110→	{
   111→		UMaterialInterface* Mat = MeshComponent->GetMaterial(i);
   112→		MaterialInfo += FString::Printf(TEXT(", Mat[%d]=%s"), i, Mat ? *Mat->GetName() : TEXT("NULL"));
   113→	}
   114→
   115→	// 추가 디버깅: 가시성 및 바운드 확인
   116→	FBoxSphereBounds Bounds = MeshComponent->Bounds;
   117→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacedObjectActor::OnMeshLoaded - SUCCESS for ObjectId=%s, MeshName=%s, Scale=%s, BoundsExtent=%s, Visible=%d, HiddenInGame=%d, %s"),
   118→		*ObjectId.ToString(),
   119→		*LoadedMesh->GetName(),
   120→		*CachedScale.ToString(),
   121→		*Bounds.BoxExtent.ToString(),
   122→		MeshComponent->IsVisible(),
   123→		IsHidden(),
   124→		*MaterialInfo);
   125→
   126→	// 메시 로드 전 배치 모드 비주얼이 요청된 경우 적용
   127→	if (bShowPlacementVisual)
   128→	{
   129→		ApplyPlacementTint();
   130→	}
   131→}
