   133→void AWjWorldPlacedObjectActor::SetHighlighted(bool bHighlight)
   134→{
   135→	if (bIsHighlighted == bHighlight)
   136→	{
   137→		return;
   138→	}
   139→
   140→	bIsHighlighted = bHighlight;
   141→
   142→	if (MeshComponent)
   143→	{
   144→		if (bHighlight)
   145→		{
   146→			// 삭제 하이라이트 우선
   147→			MeshComponent->SetRenderCustomDepth(true);
   148→			MeshComponent->SetCustomDepthStencilValue(1);
   149→		}
   150→		else if (bShowPlacementVisual)
   151→		{
   152→			// 배치 모드 비주얼 복원
   153→			MeshComponent->SetCustomDepthStencilValue(2);
   154→		}
   155→		else
   156→		{
   157→			MeshComponent->SetRenderCustomDepth(false);
   158→			MeshComponent->SetCustomDepthStencilValue(0);
   159→		}
   160→	}
   161→}
   162→
   163→void AWjWorldPlacedObjectActor::SetPlacementModeVisual(bool bEnable)
   164→{
   165→	if (bShowPlacementVisual == bEnable)
   166→	{
   167→		return;
   168→	}
   169→
   170→	bShowPlacementVisual = bEnable;
   171→
   172→	if (bEnable)
   173→	{
   174→		ApplyPlacementTint();
   175→	}
   176→	else
   177→	{
   178→		RemovePlacementTint();
   179→	}
   180→}
   181→
   182→void AWjWorldPlacedObjectActor::ApplyPlacementTint()
   183→{
   184→	if (!MeshComponent)
   185→	{
   186→		return;
   187→	}
   188→
   189→	int32 NumMats = MeshComponent->GetNumMaterials();
   190→	if (NumMats == 0)
   191→	{
   192→		return; // 메시 미로드 상태, OnMeshLoaded에서 재시도
   193→	}
   194→
   195→	// 원본 머티리얼 저장 후 DMI 틴트 적용
   196→	OriginalMaterials.Empty();
   197→	for (int32 i = 0; i < NumMats; ++i)
   198→	{
   199→		OriginalMaterials.Add(MeshComponent->GetMaterial(i));
   200→		UMaterialInstanceDynamic* DMI = MeshComponent->CreateAndSetMaterialInstanceDynamic(i);
   201→		if (DMI)
   202→		{
   203→			DMI->SetVectorParameterValue(TEXT("BaseColor"), PlacementTintColor);
   204→			DMI->SetScalarParameterValue(TEXT("Opacity"), PlacementTintOpacity);
   205→		}
   206→	}
   207→
   208→	// CustomDepth 추가 (포스트프로세스 아웃라인용)
   209→	if (!bIsHighlighted)
   210→	{
   211→		MeshComponent->SetRenderCustomDepth(true);
   212→		MeshComponent->SetCustomDepthStencilValue(2);
   213→	}
   214→}
   215→
   216→void AWjWorldPlacedObjectActor::RemovePlacementTint()
   217→{
   218→	if (!MeshComponent)
   219→	{
   220→		return;
   221→	}
   222→
   223→	// 원본 머티리얼 복원
   224→	for (int32 i = 0; i < OriginalMaterials.Num(); ++i)
   225→	{
   226→		if (i < MeshComponent->GetNumMaterials())
   227→		{
   228→			MeshComponent->SetMaterial(i, OriginalMaterials[i]);
   229→		}
   230→	}
   231→	OriginalMaterials.Empty();
   232→
   233→	if (!bIsHighlighted)
   234→	{
   235→		MeshComponent->SetRenderCustomDepth(false);
   236→		MeshComponent->SetCustomDepthStencilValue(0);
   237→	}
   238→}
