   108→void AWjWorldGameStateLobby::RespawnAllPlacedObjects()
   109→{
   110→	UWorld* World = GetWorld();
   111→	if (!World)
   112→	{
   113→		return;
   114→	}
   115→
   116→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby::RespawnAllPlacedObjects - Starting (Current SpawnedActors: %d, PlacedObjects: %d)"),
   117→		SpawnedActors.Num(), PlacedObjects.Num());
   118→
   119→	// 기존 스폰된 오브젝트 제거
   120→	for (AWjWorldPlacedObjectActor* Actor : SpawnedActors)
   121→	{
   122→		if (Actor && !Actor->IsPendingKillPending())
   123→		{
   124→			Actor->Destroy();
   125→		}
   126→	}
   127→	SpawnedActors.Empty();
   128→
   129→	// 카탈로그 폴백 로드 시도
   130→	EnsureCatalogLoaded();
   131→
   132→	// 카탈로그 없으면 스폰 불가
   133→	if (!Catalog)
   134→	{
   135→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: Cannot respawn objects - no catalog set"));
   136→		return;
   137→	}
   138→
   139→	// 새로 스폰
   140→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   141→	{
   142→		const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(Entry.ObjectId);
   143→		if (!Def)
   144→		{
   145→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: ObjectId %s not found in catalog"),
   146→				*Entry.ObjectId.ToString());
   147→			continue;
   148→		}
   149→
   150→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Spawning ObjectId=%s, MeshValid=%d, MeshPath=%s"),
   151→			*Entry.ObjectId.ToString(),
   152→			!Def->Mesh.IsNull(),
   153→			*Def->Mesh.ToString());
   154→
   155→		FActorSpawnParameters SpawnParams;
   156→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   157→
   158→		AWjWorldPlacedObjectActor* NewActor = World->SpawnActor<AWjWorldPlacedObjectActor>(
   159→			AWjWorldPlacedObjectActor::StaticClass(),
   160→			Entry.Transform.GetLocation(),
   161→			Entry.Transform.GetRotation().Rotator(),
   162→			SpawnParams
   163→		);
   164→
   165→		if (NewActor)
   166→		{
   167→			NewActor->InitializeFromSaveData(Entry.ObjectId, Entry.Transform, *Def);
   168→			SpawnedActors.Add(NewActor);
   169→		}
   170→		else
   171→		{
   172→			UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateLobby: Failed to spawn actor for ObjectId=%s"), *Entry.ObjectId.ToString());
   173→		}
   174→	}
   175→
   176→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Respawned %d objects"), SpawnedActors.Num());
   177→}
