   179→void AWjWorldGameStateLobby::EnsureCatalogLoaded()
   180→{
   181→	// 이미 Catalog가 설정되어 있으면 스킵
   182→	if (Catalog)
   183→	{
   184→		return;
   185→	}
   186→
   187→	// DeveloperSettings에서 Catalog 로드 (폴백 메커니즘)
   188→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
