   190→void UWjWorldPlacementComponent::ConfirmPlacement()
   191→{
   192→	if (CurrentMode != EPlacementMode::Placing || !PreviewActor || !bCurrentPreviewValid)
   193→	{
   194→		return;
   195→	}
   196→
   197→	if (!Catalog)
   198→	{
   199→		return;
   200→	}
   201→
   202→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(SelectedObjectId);
   203→	if (!Def)
   204→	{
   205→		return;
   206→	}
   207→
   208→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   209→	if (!DataProvider)
   210→	{
   211→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   212→		return;
   213→	}
   214→
   215→	// 배치 데이터 생성
   216→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   217→	FRotator SpawnRotation = PreviewActor->GetCurrentRotation();
   218→
   219→	FPlacedObjectSaveEntry Entry;
   220→	Entry.ObjectId = SelectedObjectId;
   221→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   222→
   223→	// JumpMap 컨텍스트: Checkpoint 오브젝트에 자동 CheckpointOrder 할당
   224→	if (CurrentContext == EPlacementContext::JumpMap)
   225→	{
   226→		FString ObjectIdStr = SelectedObjectId.ToString();
   227→		if (ObjectIdStr.Contains(TEXT("Checkpoint")))
   228→		{
   229→			int32 MaxOrder = -1;
   230→			const TArray<FPlacedObjectSaveEntry>& Existing = DataProvider->GetPlacedObjects();
   231→			for (const FPlacedObjectSaveEntry& Obj : Existing)
   232→			{
   233→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   234→				{
   235→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   236→					if (OrderStr)
   237→					{
   238→						MaxOrder = FMath::Max(MaxOrder, FCString::Atoi(**OrderStr));
   239→					}
   240→				}
   241→			}
   242→			Entry.CustomProperties.Add(TEXT("CheckpointOrder"), FString::FromInt(MaxOrder + 1));
   243→		}
   244→	}
   245→
   246→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   247→	DataProvider->AddPlacedObject(Entry);
   248→
   249→	// 새로 생성된 액터에도 배치 모드 비주얼 적용
   250→	RefreshPlacementModeVisuals();
   251→
   252→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   253→	SaveLayout();
   254→
   255→	OnObjectPlaced.Broadcast();
   256→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   257→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   258→}
