   260→void UWjWorldPlacementComponent::DeleteHoveredObject()
   261→{
   262→	if (CurrentMode != EPlacementMode::Deleting || !HoveredObject)
   263→	{
   264→		return;
   265→	}
   266→
   267→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   268→	if (!DataProvider)
   269→	{
   270→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   271→		return;
   272→	}
   273→
   274→	// DataProvider에서 해당 오브젝트 인덱스 찾기
   275→	int32 Index = FindPlacedObjectIndex(HoveredObject);
   276→	if (Index == INDEX_NONE)
   277→	{
   278→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Could not find object index for deletion"));
   279→		return;
   280→	}
   281→
   282→	HoveredObject = nullptr;
   283→
   284→	// DataProvider에서 제거 (서버에서 파괴 + 클라이언트 리플리케이션)
   285→	DataProvider->RemovePlacedObjectAt(Index);
   286→
   287→	// 로컬 SaveGame에도 저장
   288→	SaveLayout();
   289→
   290→	OnObjectDeleted.Broadcast();
   291→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object deleted at index %d"), Index);
   292→}
