   299→void UWjWorldPlacementComponent::SaveLayout()
   300→{
   301→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   302→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   303→	UWorld* World = GetWorld();
   304→	if (!World)
   305→	{
   306→		return;
   307→	}
   308→
   309→	ENetMode NetMode = World->GetNetMode();
   310→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   311→	{
   312→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   313→		return;
   314→	}
   315→
   316→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
   317→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   318→	if (!DataProvider)
   319→	{
   320→		return;
   321→	}
   322→
   323→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   324→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   325→	);
   326→
   327→	if (!SaveGame)
   328→	{
   329→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   330→		return;
   331→	}
   332→
   333→	// DataProvider의 배치 데이터 복사
   334→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   335→
   336→	// 컨텍스트별 SaveSlot 이름 사용
   337→	FString SlotName = GetCurrentSaveSlotName();
   338→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   339→	{
   340→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   341→			*SlotName, SaveGame->PlacedObjects.Num());
   342→	}
   343→	else
   344→	{
   345→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   346→	}
   347→}
