   120→	}
   121→
   122→	if (OriginalPawn.IsValid())
   123→	{
   124→		Possess(OriginalPawn.Get());
   125→	}
   126→	else
   127→	{
   128→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlayerControllerLobby: OriginalPawn is no longer valid"));
   129→	}
   130→
   131→	OriginalPawn.Reset();
