   356→void UWjWorldPlacementComponent::SaveLayoutToSlot(const FString& SlotName)
   357→{
   358→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   359→	UWorld* World = GetWorld();
   360→	if (!World)
   361→	{
   362→		return;
   363→	}
   364→
   365→	ENetMode NetMode = World->GetNetMode();
   366→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   367→	{
   368→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   369→		return;
   370→	}
   371→
   372→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   373→	if (!DataProvider)
   374→	{
   375→		return;
   376→	}
   377→
   378→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   379→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   380→	);
   381→
   382→	if (!SaveGame)
   383→	{
   384→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   385→		return;
   386→	}
   387→
   388→	// DataProvider의 배치 데이터 복사
   389→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   390→	SaveGame->SavedContext = CurrentContext;
   391→
   392→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   393→	{
   394→		LoadedSlotName = SlotName;
   395→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   396→			*SlotName, SaveGame->PlacedObjects.Num());
   397→
   398→		// AW 컨텍스트인 경우 CSV도 함께 내보내기
   399→		if (CurrentContext == EPlacementContext::ApproachingWall)
   400→		{
   401→			ExportLayoutAsCSV(SlotName);
   402→		}
   403→		// JumpMap 컨텍스트인 경우 CSV도 함께 내보내기
   404→		else if (CurrentContext == EPlacementContext::JumpMap)
   405→		{
   406→			ExportJumpMapLayoutAsCSV(SlotName);
   407→		}
   408→	}
   409→	else
   410→	{
   411→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   412→	}
   413→}
