   492→bool UWjWorldPlacementComponent::DeleteLayoutSlot(const FString& SlotName)
   493→{
   494→	// SaveGame 삭제
   495→	if (!UGameplayStatics::DeleteGameInSlot(SlotName, 0))
   496→	{
   497→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to delete save slot '%s'"), *SlotName);
   498→		return false;
   499→	}
   500→
   501→	// AW 컨텍스트: CSV 파일도 삭제
   502→	if (CurrentContext == EPlacementContext::ApproachingWall)
   503→	{
   504→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   505→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   506→		if (PlatformFile.FileExists(*CSVPath))
   507→		{
   508→			PlatformFile.DeleteFile(*CSVPath);
   509→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   510→		}
   511→	}
   512→	// JumpMap 컨텍스트: CSV 파일도 삭제
   513→	else if (CurrentContext == EPlacementContext::JumpMap)
   514→	{
   515→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   516→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   517→		if (PlatformFile.FileExists(*CSVPath))
   518→		{
   519→			PlatformFile.DeleteFile(*CSVPath);
   520→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   521→		}
   522→	}
   523→
   524→	// 현재 로드된 슬롯이면 초기화
   525→	if (LoadedSlotName == SlotName)
   526→	{
   527→		LoadedSlotName.Empty();
   528→	}
   529→
   530→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted layout slot '%s'"), *SlotName);
   531→	return true;
   532→}
